/* Rentcam advanced product runtime v7 — shared config, scoped observer */
(function(){
  if(location.pathname.startsWith('/cms'))return;
  const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const rp=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
  const cfg=()=>window.RENTCAM_CMS_CONFIG||{};
  function arr(){try{return Array.isArray(P)?P:[]}catch(e){return []}}
  function mainName(id,fallback=''){return (cfg().mainCategories||[]).find(x=>x.id===id)?.name||fallback}
  function normalize(p,v){const main=v.mainCategory||'';const images=Array.isArray(v.images)&&v.images.length?v.images:(v.image?[v.image]:[]);if(v.name)p.name=v.name;if(v.brand)p.brand=v.brand;if(main||v.category)p.cat=mainName(main,v.category||p.cat);if(v.price!==undefined)p.price=Number(v.price)||0;if(v.stock!==undefined)p.stock=Number(v.stock)||0;if(images.length){p.img=images[0];p.images=images}if(v.description!==undefined)p.description=v.description;if(Array.isArray(v.included))p.inc=v.included;if(Array.isArray(v.spec))p.spec=v.spec;p.accessories=Array.isArray(v.accessories)?v.accessories:[];p.mainCategory=main;p.subCategory=v.subCategory||'';p.placement=v.placement||'catalog';p.sortOrder=Number(v.sortOrder)||999;p.seoTitle=v.seoTitle||'';p.seoDescription=v.seoDescription||'';p.seoKeywords=v.seoKeywords||'';p.aeoQuestion=v.aeoQuestion||'';p.aeoAnswer=v.aeoAnswer||'';p.geoSummary=v.geoSummary||'';p.geoEntities=v.geoEntities||'';p._cmsActive=v.active!==false;return p}
  function sync(){const a=arr(),c=cfg(),ov=c.productOverrides||{},custom=c.customProducts||[];Object.entries(ov).forEach(([id,v])=>{const p=a.find(x=>String(x.id)===String(id));if(p)normalize(p,v)});custom.forEach(v=>{let p=a.find(x=>String(x.id)===String(v.id));if(!p){p={id:v.id,name:v.name||v.id,brand:v.brand||'',cat:mainName(v.mainCategory,v.category||'Other'),price:Number(v.price)||0,stock:Number(v.stock)||0,img:(v.images||[])[0]||v.image||'',inc:v.included||[],spec:v.spec||[]};a.push(p)}normalize(p,v)});a.sort((x,y)=>(Number(x.sortOrder)||999)-(Number(y.sortOrder)||999)||String(x.name).localeCompare(String(y.name)))}
  function productByPath(){const m=location.pathname.match(/^\/produk\/([^/?#]+)/);return m?arr().find(x=>String(x.id)===decodeURIComponent(m[1])):null}
  function meta(name,content){if(!content)return;let x=document.querySelector(`meta[name="${name}"]`);if(!x){x=document.createElement('meta');x.name=name;document.head.appendChild(x)}x.content=content}
  function applySEO(){const p=productByPath();if(!p)return;document.title=p.seoTitle||`${p.name} — Rentcam`;meta('description',p.seoDescription||p.description||'');meta('keywords',p.seoKeywords||'');let j=document.getElementById('rentcam-product-schema');if(j)j.remove();const data={'@context':'https://schema.org','@type':'Product',name:p.name,brand:{'@type':'Brand',name:p.brand||'Rentcam'},description:p.seoDescription||p.description||p.geoSummary||'',image:p.images?.length?p.images:[p.img].filter(Boolean),offers:{'@type':'Offer',priceCurrency:'IDR',price:Number(p.price)||0,availability:p.stock>0?'https://schema.org/InStock':'https://schema.org/OutOfStock'}};if(p.aeoQuestion&&p.aeoAnswer)data.subjectOf={'@type':'FAQPage',mainEntity:[{'@type':'Question',name:p.aeoQuestion,acceptedAnswer:{'@type':'Answer',text:p.aeoAnswer}}]};j=document.createElement('script');j.id='rentcam-product-schema';j.type='application/ld+json';j.textContent=JSON.stringify(data);document.head.appendChild(j)}
  function patchDetail(){const p=productByPath();if(!p)return;const root=document.querySelector('#app');if(!root)return;const h1=root.querySelector('h1');if(h1)h1.textContent=p.name;const imgs=p.images?.length?p.images:[p.img].filter(Boolean);if(imgs.length){const main=root.querySelector('.mainPhoto');if(main)main.style.backgroundImage=`url('${imgs[0]}')`;const thumbWrap=root.querySelector('.thumbs,.gallery-thumbs,.product-thumbnails');if(thumbWrap&&!thumbWrap.dataset.v7){thumbWrap.dataset.v7='1';thumbWrap.innerHTML=imgs.map((u,i)=>`<button type="button" class="adv-thumb" data-adv-img="${i}"><img src="${esc(u)}"></button>`).join('')}}if(p.accessories?.length&&!document.getElementById('rentcam-accessories')){const host=[...root.querySelectorAll('h3')].find(x=>/Included/i.test(x.textContent||''))?.parentElement||root.querySelector('.detail-ref-info')||root;const sec=document.createElement('section');sec.id='rentcam-accessories';sec.innerHTML=`<h3>Accessories</h3><ul>${p.accessories.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;host.appendChild(sec)}}
  function homeCard(p){return `<article class="home-category-card" data-product-id="${esc(p.id)}" onclick="go('/produk/${esc(p.id)}')"><div class="home-category-image"><span class="home-category-badge">${esc(p.brand||'RENTCAM')}</span><img src="${esc(p.img||'')}" loading="lazy"></div><div class="home-category-body"><div class="home-category-brand">${esc(p.brand||'')}</div><div class="home-category-name">${esc(p.name)}</div><div class="home-category-actions"><button class="home-add-cart" onclick="event.stopPropagation();add('${esc(p.id)}',1)">Tambah</button><button class="home-open-cart" onclick="event.stopPropagation();go('/cart')">🛒</button></div></div></article>`}
  function patchHome(){if(location.pathname!=='/')return;const map={'home-camera':'camera','home-lighting':'lighting','home-audio':'audio','home-package':'package'};Object.entries(map).forEach(([placement,key])=>{const a=arr().filter(p=>p._cmsActive!==false&&p.placement===placement).sort((x,y)=>(x.sortOrder||999)-(y.sortOrder||999));if(!a.length)return;const grid=document.querySelector(`#app .home-${key} .home-product-grid`);if(grid&&grid.dataset.v7Placement!==placement){grid.dataset.v7Placement=placement;grid.innerHTML=a.map(homeCard).join('')}})}
  function patchCatalog(){document.querySelectorAll('#app .pcard').forEach(c=>{const m=(c.getAttribute('onclick')||'').match(/\/produk\/([^'\")]+)/);if(!m)return;const p=arr().find(x=>String(x.id)===String(m[1]));if(p?._cmsActive===false)c.style.display='none'})}
  function patchAll(){sync();applySEO();patchDetail();patchHome();patchCatalog()}
  let queued=false;function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;patchAll()})}
  document.addEventListener('click',e=>{const b=e.target.closest?.('[data-adv-img]');if(!b)return;const p=productByPath(),u=p?.images?.[+b.dataset.advImg];const m=document.querySelector('#app .mainPhoto');if(u&&m)m.style.backgroundImage=`url('${u}')`});
  const app=document.getElementById('app');if(app)new MutationObserver(schedule).observe(app,{childList:true,subtree:true});document.addEventListener('rentcam-cms-updated',()=>{sync();schedule()});document.addEventListener('rentcam-route-change',schedule);addEventListener('popstate',schedule);setTimeout(schedule,120);
})();